#include<bits/stdc++.h>
using namespace std;

int main(){
    int N; cin >> N;
    vector<string> S(N);
    vector<int> T(N);
    pair<int,string> top,sec;
    top = sec = {0,""};
    for(int i=0; i<N; i++){
        cin >> S[i] >> T[i];
        auto p = make_pair(T[i],S[i]);
        if(top < p){
            sec = top;
            top = p;
        }
        else if(sec < p){
            sec = p;
        }
    }
    cout << sec.second << endl;
}
